#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
src = ROOT / "app/src/main/java/vn/pickpack1291/app/beta/OperationsActivity.kt"
out = ROOT / "app/build/generated/s10/vn/pickpack1291/app/beta/PatchedOperationsActivity.kt"
text = src.read_text(encoding="utf-8")


def once(old: str, new: str, label: str) -> None:
    global text
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"S10 patch anchor {label!r}: expected 1, got {count}")
    text = text.replace(old, new, 1)

# Clean PDA surfaces: white canvas, theme-tinted outlines, no grey elevation haze.
once('    private val bg:Int get()=ThemeManager.background(this)\n', '    private val bg:Int get()=Color.WHITE\n', 'white background')
once('    private val line:Int get()=ThemeManager.line(this)\n', '    private val line:Int get()=Color.argb(72,Color.red(teal),Color.green(teal),Color.blue(teal))\n', 'theme line')
for elevation in (8, 6, 3, 2, 1):
    text = text.replace(f'elevation=dp({elevation}).toFloat()', 'elevation=0f')
once('        background=outlineBg(surface,20)\n', '        background=round(ThemeManager.soft(this@OperationsActivity),20)\n', 'business card fill')
once('        background=outlineBg(surface,16)\n', '        background=round(surface,16)\n', 'bottom nav fill')

# Header: one local-time greeting + display name. No login/position lines.
old_header = '''        identity.addView(column(Color.TRANSPARENT).apply{\n            addView(txt(name.ifBlank{login},16.2f,Color.WHITE,true).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END})\n            addView(txt(position.ifBlank{roleText(role)},10.5f,Color.argb(225,255,255,255),false).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END})\n            addView(txt(login,10f,Color.argb(210,255,255,255),false).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END})\n        },LinearLayout.LayoutParams(0,-2,1f).apply{if(!isRootScreen())marginStart=dp(3)})\n'''
new_header = '''        identity.addView(txt("${greeting()}, ${name.ifBlank{login}}",16.2f,Color.WHITE,true).apply{\n            maxLines=2\n            ellipsize=android.text.TextUtils.TruncateAt.END\n        },LinearLayout.LayoutParams(0,-2,1f).apply{if(!isRootScreen())marginStart=dp(3)})\n'''
once(old_header, new_header, 'header greeting')

# Staff editor: required catalog values, no dash placeholder, normalized Vietnamese phone.
once(
    '        val phone=input("Số điện thoại",false).apply{setText(existing?.optString("phone").orEmpty())}\n',
    '''        val phone=input("Số điện thoại",false).apply{\n            setText(normalizePhone(existing?.optString("phone").orEmpty()))\n            inputType=InputType.TYPE_CLASS_PHONE\n            keyListener=DigitsKeyListener.getInstance("0123456789")\n        }\n''',
    'phone field'
)
for variable, key, field in [
    ('pos', 'DANH SÁCH NHÂN SỰ_Vị trí chính', 'main_position'),
    ('supplier', 'DANH SÁCH NHÂN SỰ_Nhà cung cấp', 'supplier'),
    ('department', 'DANH SÁCH NHÂN SỰ_Bộ phận', 'department'),
    ('site', 'DANH SÁCH NHÂN SỰ_Site', 'site'),
    ('warehouse', 'DANH SÁCH NHÂN SỰ_Kho', 'warehouse'),
]:
    old = f'        val {variable}=catalogSpinner("{key}",existing?.optString("{field}").orEmpty(),true)\n'
    new = f'        val {variable}=catalogSpinner("{key}",existing?.optString("{field}").orEmpty(),false)\n'
    once(old, new, f'{variable} required')

old_save = '''                val id=mnv.text.toString().trim();val nm=full.text.toString().trim()\n                if(id.isBlank()||nm.isBlank()){TopNotice.show(this,"MNV và họ tên là bắt buộc.",TopNotice.Kind.ERROR);return@setPositiveButton}\n                val payload=JSONObject().put("event_id",UUID.randomUUID().toString()).put("mnv",id).put("full_name",nm)\n                    .put("phone",phone.text.toString()).put("main_position",catalogSelection(pos)).put("supplier",catalogSelection(supplier))\n                    .put("department",catalogSelection(department)).put("site",catalogSelection(site)).put("warehouse",catalogSelection(warehouse))\n'''
new_save = '''                val id=mnv.text.toString().trim();val nm=full.text.toString().trim();val normalizedPhone=normalizePhone(phone.text.toString())\n                val requiredCatalog=listOf(catalogSelection(pos),catalogSelection(supplier),catalogSelection(department),catalogSelection(site),catalogSelection(warehouse))\n                if(id.isBlank()||nm.isBlank()){TopNotice.show(this,"MNV và họ tên là bắt buộc.",TopNotice.Kind.ERROR);return@setPositiveButton}\n                if(requiredCatalog.any{it.isBlank()||it=="Chưa cấu hình"}){TopNotice.show(this,"Chọn đầy đủ Vị trí chính, Nhà cung cấp, Bộ phận, Site và Kho.",TopNotice.Kind.ERROR);return@setPositiveButton}\n                if(normalizedPhone.length!=10||!normalizedPhone.startsWith("0")){TopNotice.show(this,"Số điện thoại phải đủ 10 số và bắt đầu bằng 0.",TopNotice.Kind.ERROR);return@setPositiveButton}\n                val payload=JSONObject().put("event_id",UUID.randomUUID().toString()).put("mnv",id).put("full_name",nm)\n                    .put("phone",normalizedPhone).put("main_position",catalogSelection(pos)).put("supplier",catalogSelection(supplier))\n                    .put("department",catalogSelection(department)).put("site",catalogSelection(site)).put("warehouse",catalogSelection(warehouse))\n'''
once(old_save, new_save, 'staff required save')

# History: summary + filter + grouped semantic cards + user-friendly failure descriptions.
start = text.index('    private fun historyScreen(){')
end = text.index('    private fun syncScreen(){', start)
new_history = '''    private fun historyScreen(){\n        module="HISTORY"\n        screenState="HISTORY"\n        val root=baseRoot("LỊCH SỬ")\n        val body=body()\n        val items=AppHistory.items(this)\n        var success=0\n        for(i in 0 until items.length()) if(items.optJSONObject(i)?.optBoolean("synced")==true) success++\n        val failed=items.length()-success\n        body.addView(section("Tổng quan"))\n        val summary=row(bg)\n        summary.addView(metric("Tổng",items.length().toString(),navy),LinearLayout.LayoutParams(0,-2,1f).apply{marginEnd=dp(4)})\n        summary.addView(metric("Hoàn tất",success.toString(),green),LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(2);marginEnd=dp(2)})\n        summary.addView(metric("Cần xem lại",failed.toString(),if(failed>0)red else green),LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(4)})\n        body.addView(summary,matchWrap())\n        body.addView(section("Hoạt động gần đây"))\n        val filter=spinner(arrayOf("Tất cả","Hoàn tất","Cần xem lại"))\n        body.addView(labelled("Hiển thị",filter))\n        body.addView(gap(10))\n        val box=column(bg)\n        body.addView(box,matchWrap())\n        fun render(){\n            box.removeAllViews()\n            var shown=0\n            var lastDay=""\n            val dayKey=java.text.SimpleDateFormat("yyyyMMdd",java.util.Locale.US)\n            val dayText=java.text.SimpleDateFormat("dd/MM/yyyy",java.util.Locale.US)\n            val timeText=java.text.SimpleDateFormat("HH:mm:ss",java.util.Locale.US)\n            val today=dayKey.format(java.util.Date())\n            val cal=java.util.Calendar.getInstance().apply{add(java.util.Calendar.DAY_OF_YEAR,-1)}\n            val yesterday=dayKey.format(cal.time)\n            for(i in 0 until items.length()){\n                val x=items.optJSONObject(i)?:continue\n                val ok=x.optBoolean("synced")\n                if(filter.selectedItemPosition==1&&!ok)continue\n                if(filter.selectedItemPosition==2&&ok)continue\n                val date=java.util.Date(x.optLong("at"))\n                val key=dayKey.format(date)\n                if(key!=lastDay){\n                    lastDay=key\n                    val heading=when(key){today->"Hôm nay";yesterday->"Hôm qua";else->dayText.format(date)}\n                    if(shown>0)box.addView(gap(7))\n                    box.addView(txt(heading,11.2f,navy,true))\n                    box.addView(gap(6))\n                }\n                val action=x.optString("action")\n                val card=column(surface).apply{\n                    setPadding(dp(12),dp(11),dp(12),dp(11))\n                    background=round(ThemeManager.soft(this@OperationsActivity),14)\n                    val top=row(Color.TRANSPARENT).apply{gravity=Gravity.CENTER_VERTICAL}\n                    top.addView(iconBubble(historyIcon(action),if(ok)teal else red),size(dp(38),dp(38)))\n                    top.addView(column(Color.TRANSPARENT).apply{\n                        addView(txt(AppHistory.label(action),12.6f,ink,true))\n                        addView(txt(timeText.format(date),9.4f,muted,false))\n                    },LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(9)})\n                    top.addView(status(if(ok)"Hoàn tất" else "Cần xem lại",if(ok)green else red,if(ok)Color.rgb(235,248,239) else Color.rgb(255,238,239)),LinearLayout.LayoutParams(-2,-2))\n                    addView(top,matchWrap())\n                    val detail=historyFriendlyDetail(action,x.optString("detail"),ok)\n                    if(detail.isNotBlank()){addView(gap(7));addView(txt(detail,10f,if(ok)muted else ink,false).apply{maxLines=3})}\n                }\n                box.addView(card,matchWrap());box.addView(gap(7));shown++\n            }\n            if(shown==0)box.addView(info(if(items.length()==0)"Chưa có hoạt động trên thiết bị này." else "Không có hoạt động phù hợp bộ lọc."))\n        }\n        filter.onItemSelectedListener=object:android.widget.AdapterView.OnItemSelectedListener{\n            override fun onItemSelected(p:android.widget.AdapterView<*>?,v:View?,pos:Int,id:Long){render()}\n            override fun onNothingSelected(p:android.widget.AdapterView<*>?)=Unit\n        }\n        render()\n        attach(root,body)\n    }\n\n'''
text = text[:start] + new_history + text[end:]

# Sync: useful operational dashboard; no developer/protocol jargon.
start = text.index('    private fun syncScreen(){')
end = text.index('    private fun settingsScreen(){', start)
new_sync = '''    private fun syncScreen(){\n        module="SYNC"\n        screenState="SYNC"\n        val root=baseRoot("ĐỒNG BỘ")\n        val body=body()\n        val hero=column(ThemeManager.soft(this)).apply{\n            setPadding(dp(14),dp(14),dp(14),dp(14))\n            background=round(ThemeManager.soft(this@OperationsActivity),16)\n        }\n        val headline=txt("Đang kiểm tra kết nối",15f,navy,true)\n        val subline=txt("Ứng dụng sẽ tự đồng bộ khi đang sử dụng.",10f,muted,false)\n        hero.addView(row(Color.TRANSPARENT).apply{\n            gravity=Gravity.CENTER_VERTICAL\n            addView(iconBubble(R.drawable.ic_pp_sync,teal),size(dp(44),dp(44)))\n            addView(column(Color.TRANSPARENT).apply{addView(headline);addView(gap(2));addView(subline)},LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(10)})\n        },matchWrap())\n        body.addView(hero,matchWrap())\n        body.addView(gap(10))\n        val metricsBox=column(bg);body.addView(metricsBox,matchWrap())\n        body.addView(section("Thông tin đồng bộ"))\n        val infoBox=column(bg);body.addView(infoBox,matchWrap())\n        body.addView(gap(12))\n        val refresh=primary("LÀM MỚI TRẠNG THÁI",teal){}\n        body.addView(refresh,matchWrap())\n        fun draw(connected:Boolean?,busy:Boolean=false){\n            val pending=LocalLogManager.pendingCount(this)\n            val savedAt=MasterDataCache.savedAt(this)\n            val saved=if(savedAt>0)java.text.SimpleDateFormat("dd/MM HH:mm",java.util.Locale.US).format(java.util.Date(savedAt)) else "Chưa có"\n            headline.text=when(connected){true->"Kết nối tốt";false->"Mất kết nối";null->"Đang kiểm tra kết nối"}\n            headline.setTextColor(when(connected){true->green;false->red;null->navy})\n            subline.text=when{busy->"Đang làm mới trạng thái...";connected==false->"Dữ liệu sẽ tự gửi lại khi kết nối trở lại.";else->"Dữ liệu vận hành đang sẵn sàng."}\n            metricsBox.removeAllViews()\n            val metrics=row(bg)\n            metrics.addView(metric("Mạng",when(connected){true->"Tốt";false->"Mất";null->"Đang kiểm tra"},if(connected==false)red else teal),LinearLayout.LayoutParams(0,-2,1f).apply{marginEnd=dp(4)})\n            metrics.addView(metric("Đồng bộ",when(connected){true->"Sẵn sàng";false->"Đang chờ";null->"Đang kiểm tra"},if(connected==false)orange else blue),LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(2);marginEnd=dp(2)})\n            metrics.addView(metric("Chờ gửi",pending.toString(),if(pending>0)orange else green),LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(4)})\n            metricsBox.addView(metrics,matchWrap())\n            infoBox.removeAllViews()\n            infoBox.addView(details(listOf(\n                "Dữ liệu vận hành" to "Google Sheets",\n                "Dữ liệu nhân sự" to "Cập nhật tự động",\n                "Lần làm mới dữ liệu" to saved,\n                "Kênh cập nhật" to if(BuildConfig.CHANNEL=="BETA")"Bản thử nghiệm" else "Bản ổn định",\n                "Phiên bản" to BuildConfig.VERSION_NAME,\n                "Service" to "Chưa dùng"\n            )))\n        }\n        fun refreshNow(){\n            refresh.isEnabled=false;refresh.text="ĐANG LÀM MỚI...";draw(lastConnected,true)\n            api.call("sync_status"){r->runOnUiThread{\n                if(handleAuth(r))return@runOnUiThread\n                lastConnected=r.ok\n                refreshHeaderConnection()\n                draw(lastConnected,false)\n                if(r.ok)refreshMasterCache()\n                refresh.isEnabled=true;refresh.text="LÀM MỚI TRẠNG THÁI"\n            }}\n        }\n        refresh.setOnClickListener{refreshNow()}\n        draw(lastConnected,true)\n        refreshNow()\n        attach(root,body)\n    }\n\n'''
text = text[:start] + new_sync + text[end:]

# Shared helpers.
anchor = '    private fun roleText(v:String)=when(v){"SUPERADMIN"->"Superadmin";"ADMIN"->"Admin";"USER"->"Điều phối";else->v}\n'
helpers = '''    private fun greeting():String{\n        val hour=java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)\n        return when(hour){in 5..10->"Chào buổi sáng";in 11..12->"Chào buổi trưa";in 13..17->"Chào buổi chiều";else->"Chào buổi tối"}\n    }\n    private fun normalizePhone(v:String):String{\n        val digits=v.filter{it.isDigit()}\n        return if(digits.length==9&&!digits.startsWith("0"))"0$digits" else digits\n    }\n    private fun historyIcon(action:String)=when(action){\n        "enter","exit"->R.drawable.ic_pp_scan\n        "labor_start","labor_finish"->R.drawable.ic_pp_task\n        "resource_change"->R.drawable.ic_pp_resource\n        "staff_upsert","staff_delete"->R.drawable.ic_pp_staff\n        "change_password","change_email","account_upsert","account_status"->R.drawable.ic_pp_account\n        "diagnostic_log"->R.drawable.ic_pp_log\n        else->R.drawable.ic_pp_history\n    }\n    private fun historyFriendlyDetail(action:String,raw:String,ok:Boolean):String{\n        if(ok)return when(action){\n            "enter"->"Đã ghi nhận vào ca.";"exit"->"Đã ghi nhận ra ca.";"resource_change"->"Đã cập nhật tài nguyên."\n            "labor_start"->"Đã bắt đầu công nhật.";"labor_finish"->"Đã hoàn thành công nhật."\n            "staff_upsert"->"Đã lưu thông tin nhân sự.";"staff_delete"->"Đã xóa nhân sự.";"diagnostic_log"->"Đã gửi báo lỗi."\n            "change_password"->"Đã đổi mật khẩu.";"change_email"->"Đã đổi mail.";"account_upsert"->"Đã cập nhật tài khoản.";"account_status"->"Đã đổi trạng thái tài khoản."\n            else->"Đã hoàn tất thao tác."\n        }\n        val e=raw.uppercase()\n        return when{\n            e.contains("RESOURCE_CONFLICT")->"Tài nguyên vừa được người khác nhận. Hãy chọn tài nguyên khác."\n            e.contains("USER_PICK_USED_TODAY")->"User Pick này đã được sử dụng trong ngày."\n            e.contains("USER_PACK_USED_TODAY")->"User Pack này đã được sử dụng trong ngày."\n            e.contains("LABOR_ALREADY_ACTIVE")->"Nhân sự đang có công nhật chưa hoàn thành."\n            e.contains("UNAUTHORIZED")->"Phiên đăng nhập đã thay đổi. Vui lòng đăng nhập lại."\n            e.contains("FORBIDDEN")->"Tài khoản không có quyền thực hiện thao tác này."\n            e.contains("EMPLOYEE_NOT_FOUND")->"Không tìm thấy nhân sự."\n            raw.isBlank()->"Thao tác chưa hoàn tất. Vui lòng thử lại."\n            else->"Thao tác chưa hoàn tất. Kiểm tra kết nối hoặc dữ liệu rồi thử lại."\n        }\n    }\n'''
once(anchor, helpers + anchor, 'helpers')

# Required catalog selects never contain the dash placeholder.
once('        if(values.isEmpty())values.add("—")\n', '        if(values.isEmpty())values.add("Chưa cấu hình")\n', 'catalog no dash fallback')

text = text.replace('package vn.pickpack1291.app.beta\n', 'package vn.pickpack1291.app.beta\n\n// S10_GENERATED_UI_PATCH: PDA visual/UX corrections for Beta 0.4.2-beta.10.\n', 1)
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(text, encoding="utf-8")
print(f"Generated {out} ({len(text)} chars)")
